SELECT "phone_number" 
FROM "member" 
WHERE "name" = 'Carlo Jacobs';

SELECT "department" FROM "member" WHERE "position" = 'President' OR "role" = 'President'
LIMIT 1;

However, this is based on assumptions since the schema doesn't specify these columns. The actual query would depend on how the president/department relationship is stored in the database.

SELECT MAX("budget"."amount") 
FROM "budget"
JOIN "event" ON "budget"."event_id" = "event"."id";

SELECT SUM("amount") AS total_food_expense
FROM "expense"
WHERE "category" = 'food';

SELECT 
    (SUM(CASE WHEN "event"."name" = 'Yearly Kickoff' THEN "event"."cost" ELSE 0 END) * 100.0 / SUM("event"."cost")) AS percentage
FROM "event";

SELECT COUNT(*) 
FROM "member" 
WHERE "major" = 'Physics Teaching';

SELECT DISTINCT "category"
FROM "event"
WHERE "location" = 'MU 215';
